"use client";

import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { User } from "@supabase/supabase-js";
import { getSupabaseBrowserClient } from "@/lib/supabase-browser";
import { timeLeftSeconds } from "@/lib/exam-time";
import {
  certCategory, certSlug, DEMO_DATASET, EMPTY_STORE, findCert, hangulInitials,
  loadPublishedDataset, makeId, mergeAccountStore, readLocalStore, submitIssueReport, syncAccountStore, writeLocalStore,
  type Cert, type Dataset, type GradeMode, type IssueReport, type LocalAttempt,
  type LocalStore, type Question, type QuestionTarget,
} from "@/lib/question-bank";

type Mode = "home" | "cert" | "exam" | "wrong-notes" | "bookmarks" | "history";
type ModalName = "menu" | "interim" | "exit" | "submit" | "expired" | null;

function shuffle<T>(items: T[]) { return [...items].sort(() => Math.random() - .5); }
function formatSeconds(value: number) { const seconds = Math.max(0, value); return `${Math.floor(seconds / 60).toString().padStart(2, "0")}:${(seconds % 60).toString().padStart(2, "0")}`; }
function scoreAttempt(attempt: LocalAttempt, questions: Question[]) { const correct = questions.filter((question) => attempt.answers[question.id] === question.answer).length; return questions.length ? Math.round(correct / questions.length * 100) : 0; }
function displayDate(value?: string) { return value ? new Intl.DateTimeFormat("ko-KR", { dateStyle: "medium" }).format(new Date(value)) : "-"; }

export function QuestionBankClient({ mode = "home", certParam = "", attemptId = "" }: { mode?: Mode; certParam?: string; attemptId?: string }) {
  const [dataset, setDataset] = useState<Dataset>(DEMO_DATASET);
  const [store, setStore] = useState<LocalStore>(EMPTY_STORE);
  const [hydrated, setHydrated] = useState(false);
  const [dataState, setDataState] = useState<"loading" | "live" | "demo">("loading");
  const [user, setUser] = useState<User | null>(null);
  const [authReady, setAuthReady] = useState(false);
  const syncTimer = useRef<number | null>(null);

  useEffect(() => {
    setStore(readLocalStore()); setHydrated(true);
    void loadPublishedDataset().then((live) => { if (live) { setDataset(live); setDataState("live"); } else setDataState("demo"); });
    const supabase = getSupabaseBrowserClient();
    void supabase.auth.getSession().then(({ data }) => { setUser(data.session?.user ?? null); setAuthReady(true); });
    const { data } = supabase.auth.onAuthStateChange((_event, session) => { setUser(session?.user ?? null); setAuthReady(true); });
    return () => data.subscription.unsubscribe();
  }, []);
  useEffect(() => { if (!user) return; void mergeAccountStore(readLocalStore()).then((next) => { setStore(next); writeLocalStore(next); void syncAccountStore(next); }); }, [user]);
  const saveStore = useCallback((next: LocalStore) => { setStore(next); writeLocalStore(next); if (user) { if (syncTimer.current) window.clearTimeout(syncTimer.current); syncTimer.current = window.setTimeout(() => void syncAccountStore(next), 400); } }, [user]);
  useEffect(() => () => { if (syncTimer.current) window.clearTimeout(syncTimer.current); }, []);

  if (!hydrated || dataState === "loading") return <CbtSkeleton />;
  if (mode === "home") return <CbtHome dataset={dataset} dataState={dataState} />;
  if (mode === "exam") return <ExamScreen dataset={dataset} store={store} saveStore={saveStore} certParam={certParam} attemptId={attemptId} />;
  if (mode === "wrong-notes" || mode === "bookmarks" || mode === "history") return <LearningScreen mode={mode} dataset={dataset} store={store} saveStore={saveStore} user={user} authReady={authReady} />;
  const cert = findCert(dataset, certParam);
  if (!cert) return <PageShell><EmptyState title="종목을 찾을 수 없습니다." body="종목 선택 화면에서 다시 선택해 주세요." href="/cbt/" action="종목 선택으로" /></PageShell>;
  return <CertDetail dataset={dataset} cert={cert} store={store} saveStore={saveStore} user={user} dataState={dataState} />;
}

function PageShell({ children }: { children: React.ReactNode }) { return <section className="question-bank-page"><div className="container question-bank-container">{children}</div></section>; }
function CbtSkeleton() { return <section className="question-bank-page"><div className="container question-bank-skeleton" aria-label="불러오는 중"><span /><strong /><i /><div><span /><span /></div></div></section>; }

function CbtHome({ dataset, dataState }: { dataset: Dataset; dataState: "live" | "demo" }) {
  const [query, setQuery] = useState(""); const [category, setCategory] = useState("전체"); const [builder, setBuilder] = useState(false);
  useEffect(() => { const search = new URLSearchParams(window.location.search); setCategory(search.get("cat") || "전체"); setBuilder(search.get("tab") === "builder"); }, []);
  const certs = useMemo(() => dataset.certs.map((cert) => ({ ...cert, category: cert.category || certCategory(cert.name) })), [dataset]);
  const categories = useMemo(() => ["전체", ...Array.from(new Set(certs.map((cert) => cert.category!))).sort((a, b) => a.localeCompare(b, "ko"))], [certs]);
  const filtered = certs.filter((cert) => { const word = query.replace(/\s/g, "").toLowerCase(); const name = cert.name.replace(/\s/g, "").toLowerCase(); return (category === "전체" || cert.category === category) && (!word || name.includes(word) || hangulInitials(name).includes(word)); });
  const groups = categories.filter((item) => item !== "전체").map((item) => ({ name: item, certs: filtered.filter((cert) => cert.category === item) })).filter((group) => group.certs.length);
  function chooseCategory(value: string) { setCategory(value); const url = new URL(window.location.href); if (value === "전체") url.searchParams.delete("cat"); else url.searchParams.set("cat", value); window.history.replaceState({}, "", `${url.pathname}${url.search}`); }
  return <PageShell>
    <div className="question-bank-hero cbt-home-hero"><div><span className="eyebrow">CBT MATE</span><h1>실전처럼 풀고, 약점을 바로 확인하세요.</h1><p>종목을 선택한 뒤 회차별 기출이나 모의고사를 시작하세요.</p></div><span className="question-bank-status">{dataState === "live" ? `기출 ${dataset.questions.length.toLocaleString()}문항` : "샘플 데이터"}</span></div>
    <label className="cbt-search"><span className="cbt-search-icon" aria-hidden="true" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="종목명을 검색하세요 (예: 정보처리기사)" /></label>
    {certs.length > 1 && <div className="cbt-category-chips" aria-label="종목 카테고리">{categories.map((item) => <button className={category === item ? "is-active" : ""} onClick={() => chooseCategory(item)} key={item}>{item}</button>)}</div>}
    {groups.length ? groups.map((group) => <section className="cbt-cert-group" key={group.name}>{certs.length > 1 && <div className="cbt-section-head"><h2>{group.name}</h2><span>{group.certs.length.toLocaleString()}개</span></div>}<div className="cbt-cert-grid">{group.certs.map((cert) => <Link href={`/cbt/${encodeURIComponent(certSlug(cert))}/${builder ? "?tab=builder" : ""}`} className="cbt-cert-card" key={cert.id}>{certs.length > 1 && <small>{cert.category}</small>}<strong>{cert.name}</strong><span>회차 {dataset.exams.filter((exam) => exam.certId === cert.id).length.toLocaleString()}개 · 문제 {dataset.questions.filter((question) => question.certId === cert.id).length.toLocaleString()}문항</span></Link>)}</div></section>) : <EmptyState title="검색 결과가 없습니다." body="다른 종목명이나 카테고리로 찾아보세요." action="검색 초기화" onAction={() => { setQuery(""); chooseCategory("전체"); }} />}
  </PageShell>;
}

function CertDetail({ dataset, cert, store, saveStore, user, dataState }: { dataset: Dataset; cert: Cert; store: LocalStore; saveStore: (store: LocalStore) => void; user: User | null; dataState: "live" | "demo" }) {
  const router = useRouter();
  const certExams = useMemo(() => dataset.exams.filter((exam) => exam.certId === cert.id).sort((a, b) => b.year - a.year || b.round.localeCompare(a.round)), [dataset, cert]);
  const subjects = useMemo(() => dataset.subjects.filter((subject) => subject.certId === cert.id), [dataset, cert]);
  const years = Array.from(new Set(certExams.map((exam) => exam.year))).sort((a, b) => b - a);
  const [tab, setTabState] = useState<"exams" | "subjects" | "builder" | "records">("exams"); const [year, setYear] = useState(years[0] || 0);
  const [selectedExamId, setSelectedExamId] = useState(""); const [selectedSubjects, setSelectedSubjects] = useState<string[]>([]); const [selectedExamIds, setSelectedExamIds] = useState(certExams.map((exam) => exam.id));
  const [yearExpanded, setYearExpanded] = useState(false); const [startExamId, setStartExamId] = useState(""); const [gradeMode, setGradeMode] = useState<GradeMode>("submit");
  const [count, setCount] = useState(60); const [order, setOrder] = useState<"ordered" | "random">("random"); const [target, setTarget] = useState<QuestionTarget>("all"); const [timeLimit, setTimeLimit] = useState<number | null>(60); const [toast, setToast] = useState("");
  useEffect(() => { const value = new URLSearchParams(window.location.search).get("tab"); if (value === "subjects" || value === "builder" || value === "records") setTabState(value); }, []);
  function setTab(value: typeof tab) { setTabState(value); const url = new URL(window.location.href); if (value === "exams") url.searchParams.delete("tab"); else url.searchParams.set("tab", value); window.history.replaceState({}, "", `${url.pathname}${url.search}`); }
  function begin(questionIds: string[], examIds: string[], mode: GradeMode, minutes: number | null, exact = false) { const ids = exact ? questionIds : order === "random" ? shuffle(questionIds).slice(0, count) : questionIds.slice(0, count); if (!ids.length) { setToast("선택한 범위에 출제 가능한 문제가 없습니다."); return; } const id = makeId("attempt"); const now = new Date(); const attempt: LocalAttempt = { id, config: { certId: cert.id, certSlug: certSlug(cert), examIds, subjectIds: selectedSubjects, count: ids.length, order: exact ? "ordered" : order, target, gradeMode: mode, timeLimitMinutes: minutes }, questionIds: ids, answers: {}, lockedIds: [], startedAt: now.toISOString(), endAt: minutes ? new Date(now.getTime() + minutes * 60000).toISOString() : null, status: "in_progress" }; saveStore({ ...store, attempts: [attempt, ...store.attempts] }); router.push(`/cbt/${encodeURIComponent(certSlug(cert))}/exam/${id}/`); }
  function beginExam() { const exam = certExams.find((item) => item.id === startExamId); if (exam) begin(dataset.questions.filter((question) => question.examId === exam.id).sort((a, b) => a.no - b.no).map((question) => question.id), [exam.id], gradeMode, exam.durationMinutes, true); }
  const allBuilderQuestions = dataset.questions.filter((question) => question.certId === cert.id && selectedExamIds.includes(question.examId) && (!selectedSubjects.length || selectedSubjects.includes(question.subjectId)));
  const attempted = new Set(store.attempts.flatMap((attempt) => Object.keys(attempt.answers)));
  const pool = allBuilderQuestions.filter((question) => target === "all" || (target === "unanswered" && !attempted.has(question.id)) || (target === "wrong" && !!store.wrongNotes[question.id]) || (target === "bookmark" && store.bookmarks.includes(question.id)));
  const shownYears = yearExpanded ? years : years.slice(0, 6); const rounds = certExams.filter((exam) => exam.year === year); const selectedExam = certExams.find((exam) => exam.id === selectedExamId);
  return <PageShell>
    <nav className="cbt-breadcrumb" aria-label="현재 위치"><Link href="/cbt/">CBT MATE</Link><span>›</span><Link href={`/cbt/?cat=${encodeURIComponent(cert.category || certCategory(cert.name))}`}>{cert.category || certCategory(cert.name)}</Link><span>›</span><b>{cert.name}</b></nav>
    <div className="question-bank-hero"><div><span className="eyebrow">시험 준비</span><h1>{cert.name}</h1><p>원하는 방식으로 문제를 풀고 학습 기록을 이어가세요.</p></div><span className="question-bank-status">{dataState === "live" ? "운영 중" : "샘플"}</span></div>
    <div className="question-bank-tabs">{([['exams','회차별 기출'],['subjects','단원별'],['builder','모의고사 만들기'],['records','내 기록']] as const).map(([value, label]) => <button className={tab === value ? "is-active" : ""} onClick={() => setTab(value)} key={value}>{label}</button>)}</div>
    {tab === "exams" && <div className="question-bank-grid"><section className="question-library-card"><CardHead no="01" title="연도와 회차 선택" desc="시험을 시작할 회차를 골라주세요." /><h3 className="cbt-field-label">연도 선택</h3><div className="cbt-chip-list">{shownYears.map((item) => <button className={year === item ? "is-active" : ""} onClick={() => { setYear(item); setSelectedExamId(""); }} key={item}>{item}년</button>)}</div>{years.length > 6 && <button className="cbt-more" onClick={() => setYearExpanded(!yearExpanded)}>{yearExpanded ? "접기" : "더 보기"}</button>}<h3 className="cbt-field-label">회차 선택</h3><div className="cbt-chip-list">{rounds.map((exam) => { const past = store.attempts.find((attempt) => attempt.status === "submitted" && attempt.config.examIds.includes(exam.id)); return <button className={selectedExamId === exam.id ? "is-active" : ""} onClick={() => setSelectedExamId(exam.id)} key={exam.id}>{exam.round}{user && past ? <small>✓ {past.score ?? 0}점</small> : null}</button>; })}</div></section><aside className="question-selection-panel"><div className="question-selection-top"><span className="eyebrow">선택한 시험</span><button className="button button-ghost cbt-recent" onClick={() => setStartExamId(certExams[0]?.id || "")}>가장 최근 회차로 바로 시작</button></div>{selectedExam ? <><h2>{cert.name} {selectedExam.year}년 {selectedExam.round}</h2><p>시작 전 문항 수와 채점 방식을 확인합니다.</p><div className="question-selection-actions"><button className="button button-primary" onClick={() => setStartExamId(selectedExam.id)}>시험 시작</button></div></> : <EmptyState title="회차를 선택해 주세요." body="왼쪽에서 연도와 회차를 차례로 선택하면 시작할 수 있습니다." />}</aside></div>}
    {tab === "subjects" && <div className="question-bank-grid"><section className="question-library-card cbt-subject-card"><CardHead no="02" title="단원 선택" desc="풀고 싶은 단원을 1개 이상 선택하세요." /><div className="cbt-select-all"><button onClick={() => setSelectedSubjects(selectedSubjects.length === subjects.length ? [] : subjects.map((subject) => subject.id))}>{selectedSubjects.length === subjects.length ? "전체 해제" : "전체 선택"}</button><span>{selectedSubjects.length.toLocaleString()}개 선택</span></div><div className="cbt-subject-list">{subjects.map((subject) => { const checked = selectedSubjects.includes(subject.id); const total = dataset.questions.filter((question) => question.subjectId === subject.id).length; return <label className={`cbt-subject-row${checked ? " is-selected" : ""}`} key={subject.id}><CustomCheckbox checked={checked} onChange={() => setSelectedSubjects(checked ? selectedSubjects.filter((id) => id !== subject.id) : [...selectedSubjects, subject.id])} /><strong>{subject.name}</strong><small>{total.toLocaleString()}문항</small></label>; })}</div></section><aside className="question-selection-panel"><span className="eyebrow">단원 연습</span><h2>선택한 단원으로 연습</h2><p>여러 단원을 묶어 한 번에 풀 수 있습니다.</p><div className="question-selection-actions"><button className="button button-primary" disabled={!selectedSubjects.length} onClick={() => begin(dataset.questions.filter((question) => selectedSubjects.includes(question.subjectId)).map((question) => question.id), certExams.map((exam) => exam.id), "submit", null)}>시험 시작</button>{!selectedSubjects.length && <small className="cbt-guidance">단원을 1개 이상 선택해 주세요.</small>}</div></aside></div>}
    {tab === "builder" && <div className="question-builder-grid"><section className="builder-card"><CardHead no="03" title="출제 범위" desc="회차와 단원을 조합해 모의고사를 만드세요." /><fieldset className="cbt-builder-group"><legend>회차 (다중 선택)</legend>{certExams.map((exam) => <label className="check-row" key={exam.id}><CustomCheckbox checked={selectedExamIds.includes(exam.id)} onChange={() => setSelectedExamIds(selectedExamIds.includes(exam.id) ? selectedExamIds.filter((id) => id !== exam.id) : [...selectedExamIds, exam.id])} /><span>{exam.year}년 {exam.round}</span></label>)}</fieldset><fieldset className="cbt-builder-group"><legend>단원 (선택하지 않으면 전체)</legend>{subjects.map((subject) => <label className="check-row" key={subject.id}><CustomCheckbox checked={selectedSubjects.includes(subject.id)} onChange={() => setSelectedSubjects(selectedSubjects.includes(subject.id) ? selectedSubjects.filter((id) => id !== subject.id) : [...selectedSubjects, subject.id])} /><span>{subject.name}</span><small>{dataset.questions.filter((question) => question.subjectId === subject.id).length.toLocaleString()}문항</small></label>)}</fieldset></section><aside className="builder-summary-card"><span className="eyebrow">모의고사</span><h2>모의고사 설정</h2><div className="builder-summary-fields"><label>총 문항 수<input type="number" min="1" max={Math.max(1, pool.length)} value={Math.min(count, Math.max(1, pool.length))} onChange={(event) => setCount(Number(event.target.value))} /></label><label>문제 순서<select value={order} onChange={(event) => setOrder(event.target.value as typeof order)}><option value="ordered">순서대로</option><option value="random">랜덤</option></select></label><label>출제 대상<select value={target} onChange={(event) => setTarget(event.target.value as QuestionTarget)}><option value="all">전체</option><option value="unanswered">안 푼 문제</option><option value="wrong">틀렸던 문제</option><option value="bookmark">북마크</option></select></label><label>제한시간<select value={timeLimit === null ? "none" : timeLimit} onChange={(event) => setTimeLimit(event.target.value === "none" ? null : Number(event.target.value))}><option value="none">무제한</option><option value="30">30분</option><option value="60">60분</option><option value="90">90분</option></select></label><label>채점 방식<select value={gradeMode} onChange={(event) => setGradeMode(event.target.value as GradeMode)}><option value="submit">한번에 채점</option><option value="instant">즉시 채점</option></select></label></div><div className="builder-limit"><span>선택 범위</span><strong>{pool.length.toLocaleString()}문항</strong></div><button className="button button-primary" disabled={!selectedExamIds.length || !pool.length} onClick={() => begin(pool.map((question) => question.id), selectedExamIds, gradeMode, timeLimit)}>모의고사 시작</button>{user && <button className="button button-ghost" onClick={() => { const config = { certId: cert.id, certSlug: certSlug(cert), examIds: selectedExamIds, subjectIds: selectedSubjects, count, order, target, gradeMode, timeLimitMinutes: timeLimit }; saveStore({ ...store, presets: [...store.presets, { name: `${cert.name} 프리셋`, config }] }); setToast("프리셋으로 저장했습니다."); }}>프리셋 저장</button>}</aside></div>}
    {tab === "records" && <Records cert={cert} dataset={dataset} store={store} />}
    {startExamId && <StartModal exam={certExams.find((exam) => exam.id === startExamId)!} gradeMode={gradeMode} setGradeMode={setGradeMode} onClose={() => setStartExamId("")} onStart={beginExam} />}
    <Toast message={toast} onDone={() => setToast("")} />
  </PageShell>;
}

function StartModal({ exam, gradeMode, setGradeMode, onClose, onStart }: { exam: Dataset["exams"][number]; gradeMode: GradeMode; setGradeMode: (mode: GradeMode) => void; onClose: () => void; onStart: () => void }) { return <Modal title="시험을 시작할까요?" onClose={onClose}><p>{exam.questionCount.toLocaleString()}문항 · {exam.durationMinutes.toLocaleString()}분</p><fieldset className="cbt-mode-options"><legend>채점 방식 선택</legend><label><input type="radio" name="grade-mode" checked={gradeMode === "submit"} onChange={() => setGradeMode("submit")} />한번에 채점</label><label><input type="radio" name="grade-mode" checked={gradeMode === "instant"} onChange={() => setGradeMode("instant")} />즉시 채점</label></fieldset><div className="cbt-modal-actions"><button className="button button-ghost" onClick={onClose}>취소</button><button className="button button-primary" onClick={onStart}>시험 시작</button></div></Modal>; }

function ExamScreen({ dataset, store, saveStore, certParam, attemptId }: { dataset: Dataset; store: LocalStore; saveStore: (store: LocalStore) => void; certParam: string; attemptId: string }) {
  const router = useRouter(); const attempt = store.attempts.find((item) => item.id === attemptId); const cert = findCert(dataset, certParam) || dataset.certs.find((item) => item.id === attempt?.config.certId);
  const questions = attempt?.questionIds.map((id) => dataset.questions.find((question) => question.id === id)).filter((item): item is Question => !!item) || [];
  const [selected, setSelected] = useState(0); const [secondsLeft, setSecondsLeft] = useState<number | null>(null); const [modal, setModal] = useState<ModalName>(null); const [toast, setToast] = useState(""); const [reportQuestion, setReportQuestion] = useState<Question | null>(null); const [reshuffle, setReshuffle] = useState(false); const finishedIds = useRef(new Set<string>()); const warned = useRef(false); const question = questions[selected];
  useEffect(() => { document.body.classList.add("cbt-exam-active"); return () => document.body.classList.remove("cbt-exam-active"); }, []);
  useEffect(() => { if (!attempt || attempt.status !== "in_progress") return; const beforeUnload = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ""; }; const back = () => { window.history.pushState({ cbtGuard: true }, "", window.location.href); setModal("exit"); }; window.history.pushState({ cbtGuard: true }, "", window.location.href); window.addEventListener("beforeunload", beforeUnload); window.addEventListener("popstate", back); return () => { window.removeEventListener("beforeunload", beforeUnload); window.removeEventListener("popstate", back); }; }, [attempt?.id, attempt?.status]);
  const finish = useCallback(() => { if (!attempt || attempt.status !== "in_progress" || finishedIds.current.has(attempt.id)) return; finishedIds.current.add(attempt.id); const now = new Date().toISOString(); const score = scoreAttempt(attempt, questions); const wrongNotes = { ...store.wrongNotes }; questions.forEach((item) => { const correct = attempt.answers[item.id] === item.answer; const old = wrongNotes[item.id]; if (!correct) wrongNotes[item.id] = { wrongCount: (old?.wrongCount || 0) + 1, lastWrongAt: now, memo: old?.memo || "", mastered: false }; else if (old) wrongNotes[item.id] = { ...old, mastered: true }; }); saveStore({ ...store, wrongNotes, attempts: store.attempts.map((item) => item.id === attempt.id ? { ...item, status: "submitted", submittedAt: now, score } : item) }); setModal(null); }, [attempt, questions, saveStore, store]);
  useEffect(() => { if (!attempt?.endAt || attempt.status !== "in_progress") return; const tick = () => { const left = timeLeftSeconds(attempt.endAt); setSecondsLeft(left); if (left === 0) setModal("expired"); else if (left !== null && left <= 60 && !warned.current) { warned.current = true; setToast("종료까지 1분 미만 남았습니다."); } return left; }; if (tick() === 0) return; const timer = window.setInterval(() => { if (tick() === 0) window.clearInterval(timer); }, 1000); return () => window.clearInterval(timer); }, [attempt?.endAt, attempt?.status]);
  function updateAttempt(next: LocalAttempt) { saveStore({ ...store, attempts: store.attempts.map((item) => item.id === next.id ? next : item) }); }
  const answer = useCallback((index: number) => { if (!attempt || !question || timeLeftSeconds(attempt.endAt) === 0 || attempt.lockedIds.includes(question.id)) return; updateAttempt({ ...attempt, answers: { ...attempt.answers, [question.id]: index }, lockedIds: attempt.config.gradeMode === "instant" ? [...attempt.lockedIds, question.id] : attempt.lockedIds }); setToast("답안을 저장했습니다."); }, [attempt, question, store]);
  const toggleBookmark = useCallback(() => { if (!question) return; const active = store.bookmarks.includes(question.id); saveStore({ ...store, bookmarks: active ? store.bookmarks.filter((id) => id !== question.id) : [...store.bookmarks, question.id] }); setToast(active ? "북마크를 해제했습니다." : "북마크에 추가했습니다."); }, [question, saveStore, store]);
  function leave(discard: boolean) { if (!attempt || !cert) return; if (discard) saveStore({ ...store, attempts: store.attempts.filter((item) => item.id !== attempt.id) }); router.replace(`/cbt/${encodeURIComponent(certSlug(cert))}/`); }
  function retry(ids: string[]) { if (!attempt || !cert) return; const id = makeId("attempt"); const now = new Date(); const next: LocalAttempt = { ...attempt, id, questionIds: reshuffle ? shuffle(ids) : ids, answers: {}, lockedIds: [], startedAt: now.toISOString(), endAt: attempt.config.timeLimitMinutes ? new Date(now.getTime() + attempt.config.timeLimitMinutes * 60000).toISOString() : null, submittedAt: undefined, score: undefined, status: "in_progress" }; saveStore({ ...store, attempts: [next, ...store.attempts] }); router.replace(`/cbt/${encodeURIComponent(certSlug(cert))}/exam/${id}/`); }
  useEffect(() => { if (!attempt || attempt.status !== "in_progress") return; const keyboard = (event: KeyboardEvent) => { if ((event.target as HTMLElement)?.matches("input,textarea,select")) return; if (/^[1-4]$/.test(event.key)) answer(Number(event.key) - 1); else if (event.key === "ArrowLeft") setSelected((value) => Math.max(0, value - 1)); else if (event.key === "ArrowRight") setSelected((value) => Math.min(questions.length - 1, value + 1)); else if (event.key.toLowerCase() === "b") toggleBookmark(); }; window.addEventListener("keydown", keyboard); return () => window.removeEventListener("keydown", keyboard); }, [answer, attempt, questions.length, toggleBookmark]);
  if (!attempt || !cert || !questions.length) return <PageShell><EmptyState title="응시 기록을 찾을 수 없습니다." body="저장되지 않았거나 삭제된 시험입니다." href="/cbt/" action="종목 선택으로" /></PageShell>;
  if (attempt.status === "submitted") return <ResultScreen dataset={dataset} cert={cert} attempt={attempt} questions={questions} reshuffle={reshuffle} setReshuffle={setReshuffle} onRetry={retry} onReport={setReportQuestion} reportQuestion={reportQuestion} onReportClose={() => setReportQuestion(null)} store={store} saveStore={saveStore} toast={toast} setToast={setToast} />;
  const answered = Object.keys(attempt.answers).length; const selectedAnswer = question ? attempt.answers[question.id] : undefined; const expired = secondsLeft === 0 && !!attempt.endAt; const locked = question ? attempt.lockedIds.includes(question.id) : false; const interimQuestions = questions.filter((item) => attempt.answers[item.id] !== undefined); const interimCorrect = interimQuestions.filter((item) => attempt.answers[item.id] === item.answer).length;
  return <section className="exam-page">
    <header className="exam-topbar"><button className="cbt-exam-logo" onClick={() => setModal("exit")} aria-label="CBT MATE 홈으로"><Image src="/cbtmate-logo.png" width={164} height={32} alt="CBTMATE" /></button><div className={`exam-timer${secondsLeft !== null && secondsLeft <= 300 && attempt.endAt ? " is-warning" : ""}`}><span>남은 시간</span><strong>{attempt.endAt ? secondsLeft === null ? "확인 중" : formatSeconds(secondsLeft) : "무제한"}</strong></div><div className="exam-progress"><span>진행률</span><strong>{selected + 1}/{questions.length}</strong><i><b style={{ width: `${(selected + 1) / questions.length * 100}%` }} /></i></div><button className="button button-ghost exam-palette-toggle" onClick={() => setModal("menu")}>문제 목록</button><button className="button button-primary exam-submit" onClick={() => setModal(expired ? "expired" : "submit")}>{expired ? "결과 저장" : "제출"}</button></header>
    {expired && <p className="exam-expired-notice" role="alert">제한 시간이 끝났습니다. 답안은 잠겼으며 결과 저장은 확인 후 진행됩니다.</p>}
    <div className="exam-palette">{questions.map((item, index) => <button className={`${attempt.answers[item.id] !== undefined ? "is-answered" : ""}${index === selected ? " is-current" : ""}${store.bookmarks.includes(item.id) ? " is-bookmarked" : ""}`} onClick={() => setSelected(index)} key={item.id}>{index + 1}</button>)}</div>
    <article className="exam-content"><div className="exam-question-head"><span className="eyebrow">QUESTION {selected + 1}</span><div><button className={`exam-bookmark${store.bookmarks.includes(question.id) ? " is-active" : ""}`} onClick={toggleBookmark}><span>☆</span> 북마크</button><button className="cbt-report-link" onClick={() => setReportQuestion(question)}>오류 신고</button></div></div><h1>{question.stem}</h1>{question.images.length > 0 && <div className="question-image-list">{question.images.map((src) => <img src={src} alt="문항 참고 이미지" key={src} />)}</div>}<div className="choice-list">{question.choices.map((choice, index) => { const chosen = selectedAnswer === index; const correct = locked && question.answer === index; const wrong = locked && chosen && !correct; return <button className={`choice-button${chosen ? " is-selected" : ""}${correct ? " is-correct" : ""}${wrong ? " is-wrong" : ""}`} disabled={locked || expired} onClick={() => answer(index)} key={`${choice.label}-${index}`}><b>{choice.label}</b><span>{choice.text}</span>{correct && <em>정답</em>}{wrong && <em>오답</em>}</button>; })}</div>{locked && <div className={`instant-feedback ${selectedAnswer === question.answer ? "is-correct" : "is-wrong"}`}><strong>{selectedAnswer === question.answer ? "✓ 정답입니다." : "✕ 오답입니다."}</strong><p>{question.explanation || "등록된 해설이 없습니다."}</p></div>}<div className="exam-nav"><button className="button button-ghost" disabled={!selected} onClick={() => setSelected(selected - 1)}>이전</button><button className="button button-primary" disabled={selected === questions.length - 1} onClick={() => setSelected(selected + 1)}>다음</button></div><p className="cbt-shortcuts">단축키 1~4 보기 선택 · ←/→ 이전/다음 · B 북마크</p></article>
    {modal === "menu" && <Modal title="문제 목록" onClose={() => setModal(null)} initialFocus><div className="cbt-menu-actions"><button className="button button-primary" autoFocus onClick={() => setModal(null)}>계속 풀기</button><button className="button button-ghost" onClick={() => setModal("interim")}>중간 채점</button><button className="button button-ghost" onClick={() => setModal("exit")}>목록으로 나가기</button></div></Modal>}
    {modal === "interim" && <Modal title="중간 채점 결과" onClose={() => setModal(null)}><div className="cbt-interim-summary"><strong>{interimQuestions.length ? Math.round(interimCorrect / interimQuestions.length * 100) : 0}%</strong><span>정답률</span><span>푼 문제 {interimQuestions.length.toLocaleString()}개</span><span>안 푼 문제 {(questions.length - interimQuestions.length).toLocaleString()}개</span></div><div className="result-grid">{questions.map((item, index) => <div className={`result-q${attempt.answers[item.id] === undefined ? "" : attempt.answers[item.id] === item.answer ? " is-correct" : " is-wrong"}`} key={item.id}><b>{index + 1}</b><span>{attempt.answers[item.id] === undefined ? "-" : attempt.answers[item.id] === item.answer ? "O" : "X"}</span></div>)}</div><div className="cbt-modal-actions"><button className="button button-primary" onClick={() => setModal(null)}>계속 풀기</button></div></Modal>}
    {modal === "exit" && <Modal title="시험을 나갈까요?" onClose={() => setModal(null)}><p>답안은 선택할 때마다 자동 저장됩니다.</p><div className="cbt-menu-actions"><button className="button button-primary" autoFocus onClick={() => leave(false)}>저장하고 나가기</button><button className="button button-ghost" onClick={() => leave(true)}>저장하지 않고 나가기</button><button className="button button-ghost" onClick={() => setModal(null)}>계속 풀기</button></div></Modal>}
    {modal === "submit" && <Modal title="답안을 제출할까요?" onClose={() => setModal(null)}><p>안 푼 문제 <strong>{(questions.length - answered).toLocaleString()}개</strong>가 있습니다. 제출하면 시험이 종료됩니다.</p><div className="cbt-modal-actions"><button className="button button-ghost" onClick={() => setModal(null)}>계속 풀기</button><button className="button button-primary" onClick={finish}>제출하고 채점</button></div></Modal>}
    {modal === "expired" && <Modal title="제한 시간이 끝났습니다" onClose={() => setModal(null)} initialFocus><p>답안은 더 수정할 수 없습니다. 결과를 저장하고 확인할까요? 안 푼 문제 {(questions.length - answered).toLocaleString()}개도 오답으로 채점됩니다.</p><div className="cbt-modal-actions"><button className="button button-ghost" onClick={() => setModal(null)}>나중에 결정</button><button className="button button-primary" onClick={finish}>결과 저장하고 보기</button></div></Modal>}
    {reportQuestion && <ReportModal question={reportQuestion} attemptId={attempt.id} store={store} saveStore={saveStore} onClose={() => setReportQuestion(null)} onDone={() => { setReportQuestion(null); setToast("오류 신고를 접수했습니다."); }} />}<Toast message={toast} onDone={() => setToast("")} />
  </section>;
}

function ResultScreen({ dataset, cert, attempt, questions, reshuffle, setReshuffle, onRetry, onReport, reportQuestion, onReportClose, store, saveStore, toast, setToast }: { dataset: Dataset; cert: Cert; attempt: LocalAttempt; questions: Question[]; reshuffle: boolean; setReshuffle: (value: boolean) => void; onRetry: (ids: string[]) => void; onReport: (question: Question) => void; reportQuestion: Question | null; onReportClose: () => void; store: LocalStore; saveStore: (store: LocalStore) => void; toast: string; setToast: (message: string) => void }) {
  const [selectedIndex, setSelectedIndex] = useState(0);
  useEffect(() => { document.title = "시험 결과 | CBT MATE"; }, []);
  const correct = questions.filter((question) => attempt.answers[question.id] === question.answer).length;
  const unanswered = questions.filter((question) => attempt.answers[question.id] === undefined).length;
  const score = attempt.score ?? (questions.length ? Math.round(correct / questions.length * 100) : 0);
  const wrongIds = questions.filter((question) => attempt.answers[question.id] !== question.answer).map((question) => question.id);
  const exam = dataset.exams.find((item) => attempt.config.examIds.includes(item.id));
  const spent = Math.max(0, Math.round((new Date(attempt.submittedAt || Date.now()).getTime() - new Date(attempt.startedAt).getTime()) / 60000));
  const subjectStats = dataset.subjects.filter((subject) => questions.some((question) => question.subjectId === subject.id)).map((subject) => {
    const scoped = questions.filter((question) => question.subjectId === subject.id);
    const right = scoped.filter((question) => attempt.answers[question.id] === question.answer).length;
    return { name: subject.name, rate: Math.round(right / scoped.length * 100) };
  });
  const selected = questions[selectedIndex];
  return <section className="exam-page"><div className="result-page">
    <div className={`result-hero${score >= (exam?.passScore || 60) ? " is-pass" : " is-fail"}`}>
      <span className="eyebrow">시험 결과</span>
      <strong className="result-score"><span>{score}</span><small>점</small></strong>
      <h1>{score >= (exam?.passScore || 60) ? "합격 기준을 넘었습니다." : "조금 더 복습해 보세요."}</h1>
      <p>정답 {correct}문항 · 오답 {questions.length - correct - unanswered}문항 · 미응답 {unanswered}문항 · 소요시간 {spent}분</p>
      <p>{displayDate(attempt.submittedAt)} · 전체 {questions.length}문항</p>
    </div>
    <div className="result-actions" aria-label="결과 다음 단계">
      <button className="button button-primary" disabled={!wrongIds.length} onClick={() => onRetry(wrongIds)}>오답·미응답 다시 풀기</button>
      <Link className="button button-secondary" href="/cbt/wrong-notes/">오답노트</Link>
      <button className="button button-ghost" onClick={() => onRetry(attempt.questionIds)}>전체 다시 풀기</button>
      <Link className="button button-ghost" href={`/cbt/${encodeURIComponent(certSlug(cert))}/`}>종목으로 돌아가기</Link>
    </div>
    <label className="cbt-reshuffle"><CustomCheckbox checked={reshuffle} onChange={() => setReshuffle(!reshuffle)} />재도전할 때 순서 다시 섞기</label>
    <section className="cbt-subject-stats"><h2>단원별 정답률</h2>{subjectStats.map((item) => <div key={item.name}><span>{item.name}</span><i role="img" aria-label={`정답률 ${item.rate}%`}><b style={{ width: `${item.rate}%`, minWidth: item.rate ? 8 : 0 }} /></i><strong>{item.rate}%</strong></div>)}</section>
    <section className="result-review"><h2>문항별 결과</h2><p>번호를 선택하면 해당 문제와 해설을 볼 수 있습니다.</p>
      <div className="result-number-grid" aria-label="문항별 결과">{questions.map((question, index) => {
        const status = attempt.answers[question.id] === undefined ? "미응답" : attempt.answers[question.id] === question.answer ? "정답" : "오답";
        return <button type="button" className={`result-number is-${status === "정답" ? "correct" : status === "오답" ? "wrong" : "unanswered"}`} aria-label={`${index + 1}번 ${status} 상세 보기`} aria-pressed={selectedIndex === index} onClick={() => setSelectedIndex(index)} key={question.id}><b>{index + 1}</b><span aria-hidden="true">{status === "정답" ? "O" : status === "오답" ? "X" : "–"}</span></button>;
      })}</div>
      {selected && <article className="result-detail"><div className="result-detail-head"><strong>{selectedIndex + 1}번 · {attempt.answers[selected.id] === undefined ? "미응답" : attempt.answers[selected.id] === selected.answer ? "정답" : "오답"}</strong><button className="cbt-report-link" onClick={() => onReport(selected)}>오류 신고</button></div><h3>{selected.stem}</h3>{selected.images.length > 0 && <div className="question-image-list">{selected.images.map((src) => <img src={src} alt="문항 참고 이미지" key={src} />)}</div>}<ol className="result-choice-list">{selected.choices.map((choice, index) => <li className={`${index === selected.answer ? "is-correct" : ""}${index === attempt.answers[selected.id] && index !== selected.answer ? " is-wrong" : ""}`} key={`${choice.label}-${index}`}><span>{choice.label} {choice.text}</span>{index === selected.answer && <b>정답</b>}{index === attempt.answers[selected.id] && index !== selected.answer && <b>내 답</b>}</li>)}</ol><div className="result-explanation"><strong>해설</strong><p>{selected.explanation || "등록된 해설이 없습니다."}</p></div></article>}
    </section>
  </div>{reportQuestion && <ReportModal question={reportQuestion} attemptId={attempt.id} store={store} saveStore={saveStore} onClose={onReportClose} onDone={() => { onReportClose(); setToast("오류 신고를 접수했습니다."); }} />}<Toast message={toast} onDone={() => setToast("")} /></section>;
}

function LearningScreen({ mode, dataset, store, saveStore, user, authReady }: { mode: "wrong-notes" | "bookmarks" | "history"; dataset: Dataset; store: LocalStore; saveStore: (store: LocalStore) => void; user: User | null; authReady: boolean }) {
  const router = useRouter();
  const [certId, setCertId] = useState("all");
  const [subjectId, setSubjectId] = useState("all");
  const [period, setPeriod] = useState("all");
  const [page, setPage] = useState(1);
  const [editingMemoId, setEditingMemoId] = useState<string | null>(null);
  const [explanationQuestion, setExplanationQuestion] = useState<Question | null>(null);
  const [deletingQuestionId, setDeletingQuestionId] = useState<string | null>(null);
  const title = mode === "wrong-notes" ? "오답노트" : mode === "bookmarks" ? "북마크" : "내 기록";
  if (!authReady) return <CbtSkeleton />;
  if (!user) return <PageShell><div className="question-bank-hero"><div><span className="eyebrow">내 학습</span><h1>{title}</h1><p>로그인하면 학습 기록을 안전하게 이어서 볼 수 있습니다.</p></div></div><EmptyState title="로그인이 필요한 화면입니다." body="로그인 후 오답, 북마크와 응시 기록을 확인하세요." href={`/account/login/?next=${encodeURIComponent(`/cbt/${mode}/`)}`} action="로그인" /></PageShell>;

  const cutoff = period === "all" ? 0 : Date.now() - Number(period) * 86400000;
  const filterQuestion = (question: Question) => (certId === "all" || question.certId === certId) && (subjectId === "all" || question.subjectId === subjectId);
  const wrongQuestions = dataset.questions.filter((question) => store.wrongNotes[question.id] && filterQuestion(question) && (!cutoff || new Date(store.wrongNotes[question.id].lastWrongAt).getTime() >= cutoff)).sort((a, b) => new Date(store.wrongNotes[b.id].lastWrongAt).getTime() - new Date(store.wrongNotes[a.id].lastWrongAt).getTime());
  const bookmarkQuestions = dataset.questions.filter((question) => store.bookmarks.includes(question.id) && filterQuestion(question));
  const bookmarkBatch = bookmarkQuestions.filter((question) => question.certId === bookmarkQuestions[0]?.certId);
  const attempts = store.attempts.filter((attempt) => attempt.status === "submitted" && (certId === "all" || attempt.config.certId === certId));
  const pageCount = Math.max(1, Math.ceil(wrongQuestions.length / 20));
  const currentPage = Math.min(page, pageCount);
  const visibleWrongQuestions = wrongQuestions.slice((currentPage - 1) * 20, currentPage * 20);
  const batchCertId = visibleWrongQuestions[0]?.certId;
  const retryBatch = visibleWrongQuestions.filter((question) => question.certId === batchCertId);
  const batchCert = dataset.certs.find((cert) => cert.id === batchCertId);
  const resetPage = () => setPage(1);

  function retry(questionIds: string[]) {
    const first = dataset.questions.find((question) => question.id === questionIds[0]);
    const cert = dataset.certs.find((item) => item.id === first?.certId);
    if (!first || !cert) return;
    const scopedIds = questionIds.filter((id) => dataset.questions.some((question) => question.id === id && question.certId === cert.id));
    const id = makeId("attempt");
    const attempt: LocalAttempt = {
      id,
      config: { certId: cert.id, certSlug: certSlug(cert), examIds: Array.from(new Set(scopedIds.map((qid) => dataset.questions.find((question) => question.id === qid)?.examId).filter(Boolean) as string[])), subjectIds: [], count: scopedIds.length, order: "ordered", target: mode === "bookmarks" ? "bookmark" : "wrong", gradeMode: "submit", timeLimitMinutes: null },
      questionIds: scopedIds, answers: {}, lockedIds: [], startedAt: new Date().toISOString(), endAt: null, status: "in_progress",
    };
    saveStore({ ...store, attempts: [attempt, ...store.attempts] });
    router.push(`/cbt/${encodeURIComponent(certSlug(cert))}/exam/${id}/`);
  }

  return <PageShell>
    <div className="question-bank-hero"><div><span className="eyebrow">내 학습</span><h1>{title}</h1><p>{mode === "history" ? "응시 흐름과 약점 단원을 한눈에 확인하세요." : mode === "wrong-notes" ? "틀린 문제를 모아 다시 풀고 메모로 복습하세요." : "저장한 문제를 모아 다시 학습하세요."}</p></div></div>
    <div className="cbt-learning-filters">
      <select aria-label="종목 필터" value={certId} disabled={mode === "bookmarks" && !store.bookmarks.length} onChange={(event) => { setCertId(event.target.value); setSubjectId("all"); resetPage(); }}><option value="all">전체 종목</option>{dataset.certs.map((cert) => <option value={cert.id} key={cert.id}>{cert.name}</option>)}</select>
      {mode !== "history" && <select aria-label="단원 필터" value={subjectId} disabled={mode === "bookmarks" && !store.bookmarks.length} onChange={(event) => { setSubjectId(event.target.value); resetPage(); }}><option value="all">전체 단원</option>{dataset.subjects.filter((subject) => certId === "all" || subject.certId === certId).map((subject) => <option value={subject.id} key={subject.id}>{subject.name}</option>)}</select>}
      {mode === "wrong-notes" && <select aria-label="기간 필터" value={period} onChange={(event) => { setPeriod(event.target.value); resetPage(); }}><option value="all">전체 기간</option><option value="7">최근 7일</option><option value="30">최근 30일</option><option value="90">최근 90일</option></select>}
    </div>
    {mode === "wrong-notes" && (wrongQuestions.length ? <section className="records-card">
      <div className="cbt-section-head"><h2>틀린 문제 <small>{wrongQuestions.length.toLocaleString()}문항</small></h2><button className="button button-primary" onClick={() => retry(retryBatch.map((question) => question.id))}>{batchCert?.name} 현재 목록 {retryBatch.length}문항 다시 풀기</button></div>
      <p className="cbt-list-range" aria-live="polite">{wrongQuestions.length.toLocaleString()}문항 중 {(currentPage - 1) * 20 + 1}~{Math.min(currentPage * 20, wrongQuestions.length)}번 표시</p>
      {visibleWrongQuestions.map((question) => { const note = store.wrongNotes[question.id]; return <article className="cbt-learning-row" key={question.id}>
        <div><small>{dataset.certs.find((cert) => cert.id === question.certId)?.name} · {dataset.subjects.find((subject) => subject.id === question.subjectId)?.name}</small><strong>{question.no}. {question.stem}</strong><span>{note.wrongCount.toLocaleString()}회 틀림 · 최근 {displayDate(note.lastWrongAt)} {note.mastered ? "· 복습 완료" : ""}</span></div>
        <div className="cbt-row-controls"><div className="cbt-row-actions"><button type="button" onClick={() => setExplanationQuestion(question)}>해설</button><button type="button" onClick={() => retry([question.id])}>다시 풀기</button><button type="button" aria-expanded={editingMemoId === question.id} onClick={() => setEditingMemoId(editingMemoId === question.id ? null : question.id)}>{note.memo ? "메모 수정" : "메모"}</button><button type="button" onClick={() => setDeletingQuestionId(question.id)}>삭제</button></div>{editingMemoId === question.id && <textarea aria-label={`${question.no}번 오답 메모`} rows={3} placeholder="오답 원인을 적어 보세요." value={note.memo} onChange={(event) => saveStore({ ...store, wrongNotes: { ...store.wrongNotes, [question.id]: { ...note, memo: event.target.value } } })} />}</div>
      </article>; })}
      {pageCount > 1 && <nav className="cbt-pagination" aria-label="오답노트 페이지"><button className="button button-ghost" disabled={currentPage === 1} onClick={() => setPage(currentPage - 1)}>이전</button><span aria-live="polite">{currentPage} / {pageCount}</span><button className="button button-ghost" disabled={currentPage === pageCount} onClick={() => setPage(currentPage + 1)}>다음</button></nav>}
    </section> : <EmptyState title="조건에 맞는 오답이 없습니다." body="문제를 풀고 틀린 문항이 생기면 여기에 자동으로 모입니다." href="/cbt/" action="문제 풀기" />)}
    {mode === "bookmarks" && (bookmarkQuestions.length ? <section className="records-card"><div className="cbt-section-head"><h2>저장한 문제</h2><button className="button button-primary" onClick={() => retry(bookmarkBatch.map((question) => question.id))}>{dataset.certs.find((cert) => cert.id === bookmarkQuestions[0].certId)?.name} {bookmarkBatch.length}문항 다시 풀기</button></div>{bookmarkQuestions.map((question) => <article className="cbt-learning-row" key={question.id}><div><small>{dataset.certs.find((cert) => cert.id === question.certId)?.name}</small><strong>{question.no}. {question.stem}</strong></div><button className="button button-ghost" onClick={() => saveStore({ ...store, bookmarks: store.bookmarks.filter((id) => id !== question.id) })}>북마크 해제</button></article>)}</section> : <EmptyState title="저장한 북마크가 없습니다." body="시험 화면에서 다시 보고 싶은 문제를 저장해 보세요." href="/cbt/" action="문제 풀기" />)}
    {mode === "history" && (attempts.length ? <div className="records-grid"><section className="records-card"><h2>응시 이력</h2>{attempts.map((attempt) => { const cert = dataset.certs.find((item) => item.id === attempt.config.certId); const exam = dataset.exams.find((item) => attempt.config.examIds.length === 1 && attempt.config.examIds[0] === item.id); return <div className="record-row" key={attempt.id}><span>{cert?.name || "종목 정보 없음"}<small>{exam ? `${exam.year}년 ${exam.round}` : "모의고사"} · {displayDate(attempt.submittedAt)}</small></span><strong>{attempt.score ?? 0}점</strong>{cert ? <Link className="button button-ghost" href={`/cbt/${encodeURIComponent(certSlug(cert))}/exam/${attempt.id}/`}>결과 다시 보기</Link> : <span className="record-unavailable">결과 확인 불가</span>}</div>; })}</section><section className="records-card"><h2>종목별 단원 정답률</h2>{dataset.subjects.map((subject) => { const answers = attempts.flatMap((attempt) => attempt.questionIds.map((id) => ({ attempt, question: dataset.questions.find((question) => question.id === id) }))).filter((item) => item.question?.subjectId === subject.id); if (!answers.length) return null; const rate = Math.round(answers.filter(({ attempt, question }) => question && attempt.answers[question.id] === question.answer).length / answers.length * 100); const cert = dataset.certs.find((item) => item.id === subject.certId); return <div className="cbt-rate-row" key={subject.id}><span>{cert?.name} · {subject.name}</span><i role="img" aria-label={`정답률 ${rate}%`}><b style={{ width: `${rate}%`, minWidth: rate ? 8 : 0 }} /></i><strong>{rate}%</strong></div>; })}</section></div> : <EmptyState title="응시 기록이 없습니다." body="첫 시험을 완료하면 점수와 정답률이 여기에 표시됩니다." href="/cbt/" action="종목 선택" />)}
    {explanationQuestion && <Modal title={`${explanationQuestion.no}번 해설`} onClose={() => setExplanationQuestion(null)}><p>{explanationQuestion.explanation || "등록된 해설이 없습니다."}</p><div className="cbt-modal-actions"><button className="button button-primary" onClick={() => setExplanationQuestion(null)}>닫기</button></div></Modal>}
    {deletingQuestionId && <Modal title="오답노트에서 삭제할까요?" onClose={() => setDeletingQuestionId(null)}><p>삭제한 문제는 다시 틀리면 오답노트에 저장됩니다.</p><div className="cbt-modal-actions"><button className="button button-ghost" onClick={() => setDeletingQuestionId(null)}>취소</button><button className="button button-primary" onClick={() => { const next = { ...store.wrongNotes }; delete next[deletingQuestionId]; saveStore({ ...store, wrongNotes: next }); setDeletingQuestionId(null); }}>삭제</button></div></Modal>}
  </PageShell>;
}

function Records({ cert, dataset, store }: { cert: Cert; dataset: Dataset; store: LocalStore }) { const attempts = store.attempts.filter((attempt) => attempt.config.certId === cert.id); return attempts.length ? <section className="records-card"><h2>내 기록</h2>{attempts.map((attempt) => { const exam = dataset.exams.find((item) => attempt.config.examIds.length === 1 && attempt.config.examIds[0] === item.id); return <div className="record-row" key={attempt.id}><span>{exam ? `${exam.year}년 ${exam.round}` : "모의고사"}<small>{displayDate(attempt.submittedAt || attempt.startedAt)}</small></span><strong>{attempt.status === "submitted" ? `${attempt.score ?? 0}점` : "진행 중"}</strong><Link className="button button-ghost" href={`/cbt/${encodeURIComponent(certSlug(cert))}/exam/${attempt.id}/`}>{attempt.status === "submitted" ? "결과 보기" : "이어서 풀기"}</Link></div>; })}</section> : <EmptyState title="아직 학습 기록이 없습니다." body="회차별 기출이나 모의고사를 시작해 보세요." />; }
function CardHead({ no, title, desc }: { no: string; title: string; desc: string }) { return <div className="question-card-head"><span>{no}</span><div><strong>{title}</strong><p>{desc}</p></div></div>; }
function CustomCheckbox({ checked, onChange, disabled = false }: { checked: boolean; onChange: () => void; disabled?: boolean }) { return <span className="cbt-checkbox"><input type="checkbox" checked={checked} onChange={onChange} disabled={disabled} /><span aria-hidden="true">{checked && <svg viewBox="0 0 16 16"><path d="m3 8 3 3 7-7" /></svg>}</span></span>; }
function Modal({ title, children, onClose, initialFocus = false }: { title: string; children: React.ReactNode; onClose: () => void; initialFocus?: boolean }) { const ref = useRef<HTMLDialogElement>(null); useEffect(() => { const dialog = ref.current; if (!dialog) return; if (!dialog.open) dialog.showModal(); if (initialFocus) dialog.querySelector<HTMLElement>(".cbt-modal-actions .button, .cbt-menu-actions .button")?.focus(); }, [initialFocus]); return <dialog className="cbt-modal" aria-labelledby="cbt-modal-title" ref={ref} onClose={onClose}><div className="cbt-modal-head"><h2 id="cbt-modal-title">{title}</h2><button onClick={() => ref.current?.close()} aria-label="닫기">×</button></div>{children}</dialog>; }
function EmptyState({ title, body, href, action, onAction }: { title: string; body: string; href?: string; action?: string; onAction?: () => void }) { return <div className="question-empty cbt-empty"><strong>{title}</strong><p>{body}</p>{href && action ? <Link className="button button-primary" href={href}>{action}</Link> : onAction && action ? <button onClick={onAction}>{action}</button> : null}</div>; }
function Toast({ message, onDone }: { message: string; onDone: () => void }) { useEffect(() => { if (!message) return; const timer = window.setTimeout(onDone, 2200); return () => window.clearTimeout(timer); }, [message, onDone]); return message ? <div className="cbt-toast" role="status">{message}</div> : null; }
function ReportModal({ question, attemptId, store, saveStore, onClose, onDone }: { question: Question; attemptId: string; store: LocalStore; saveStore: (store: LocalStore) => void; onClose: () => void; onDone: () => void }) { const [kind, setKind] = useState<IssueReport["kind"]>("wrong_answer"); const [memo, setMemo] = useState(""); function submit() { const report: IssueReport = { id: makeId("report"), questionId: question.id, attemptId, kind, memo, createdAt: new Date().toISOString(), status: "open" }; saveStore({ ...store, issueReports: [report, ...store.issueReports] }); void submitIssueReport(report).catch(() => undefined); onDone(); } return <Modal title="문제 오류 신고" onClose={onClose}><div className="builder-fields"><label>오류 유형<select value={kind} onChange={(event) => setKind(event.target.value as IssueReport["kind"])}><option value="wrong_answer">잘못된 정답</option><option value="broken_image">이미지 깨짐</option><option value="missing_choice">보기 누락</option><option value="other">기타</option></select></label><label>메모<textarea rows={4} value={memo} onChange={(event) => setMemo(event.target.value)} placeholder="확인할 내용을 적어 주세요." /></label></div><div className="cbt-modal-actions"><button className="button button-ghost" onClick={onClose}>취소</button><button className="button button-primary" onClick={submit}>신고 접수</button></div></Modal>; }
